//! The GlobeCraft logo (the Bloom mark) for the About window and the About command icon.
//! The masks are white and generated by `scripts/generate_logos.py`; they are tinted when drawn,
//! so the logo follows the theme like every other icon.
use eframe::egui::{self, Color32, Painter, Rect, TextureHandle};

const BLOOM_MASK_LARGE_PNG: &[u8] =
    include_bytes!("../../../../../assets/branding/globecraft/logo/globecraft-bloom-mask-256.png");
/// Generalised for small sizes, so the continents stay readable in menus and the ribbon.
const BLOOM_MASK_SMALL_PNG: &[u8] =
    include_bytes!("../../../../../assets/branding/globecraft/logo/globecraft-bloom-mask-64.png");
/// Drawings up to this many physical pixels use the small mask.
const SMALL_MASK_MAX_PX: f32 = 64.0;
/// Slate ink of the light and dark logo (see `assets/branding/globecraft/README.md`).
const LOGO_INK_LIGHT: Color32 = Color32::from_rgb(0x2f, 0x44, 0x59);
const LOGO_INK_DARK: Color32 = Color32::from_rgb(0xb4, 0xc3, 0xd2);

/// The brand ink for the current theme.
pub(super) fn logo_ink(dark_mode: bool) -> Color32 {
    if dark_mode {
        LOGO_INK_DARK
    } else {
        LOGO_INK_LIGHT
    }
}

/// Paints the Bloom into `rect`, tinted `ink`. Draws nothing if the bundled mask cannot be decoded.
pub(super) fn paint_bloom(painter: &Painter, rect: Rect, ink: Color32) {
    let ctx = painter.ctx();
    let small = rect.width().max(rect.height()) * ctx.pixels_per_point() <= SMALL_MASK_MAX_PX;
    if let Some(mask) = mask(ctx, small) {
        let uv = Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0));
        painter.image(mask.id(), rect, uv, ink);
    }
}

/// Decodes a mask once and keeps the texture in egui's temporary storage.
fn mask(ctx: &egui::Context, small: bool) -> Option<TextureHandle> {
    let id = egui::Id::new(("globecraft-bloom-mask", small));
    if let Some(texture) = ctx.data(|data| data.get_temp::<TextureHandle>(id)) {
        return Some(texture);
    }
    let bytes = if small {
        BLOOM_MASK_SMALL_PNG
    } else {
        BLOOM_MASK_LARGE_PNG
    };
    let image = image::load_from_memory(bytes).ok()?.to_rgba8();
    let size = [image.width() as usize, image.height() as usize];
    let texture = ctx.load_texture(
        "globecraft-bloom-mask",
        egui::ColorImage::from_rgba_unmultiplied(size, image.as_raw()),
        egui::TextureOptions::LINEAR,
    );
    ctx.data_mut(|data| data.insert_temp(id, texture.clone()));
    Some(texture)
}
